#define N R.x
vec2 R;
#define Main void mainImage(out vec4 Q, in vec2 U) {R = iResolution.xy;
#define A(u) texture(iChannel0,(u)/R)
#define B(u) texture(iChannel1,(u)/R)
#define C(u) texture(iChannel2,(u)/R)
#define D(u) texture(iChannel3,(u)/R)

#define vel(v) v*inversesqrt(1.+dot(v,v))

 #define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))

 vec4 hash(vec4 p4)
{
    p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

vec2 init (float i) {
    float x = floor(i/N*5.)/5.*2.-1.;
    i = mod(i,N/5.);
    return .5*R + .2*R.x*vec2(1.5*x+.2*sin(2.*i/N*6.2*10.+.5*iTime),-1.+3.*(.8+.6*sin(10.*x+1.*iTime))*5.*i/N);
}
Main 
    if (U.x>N||U.y>1.) discard;
    Q = A(U);
    float I = floor(U.x);
    vec2 Q0 = init(I);
    vec2 f = vec2(0,-.001);
    for (float i = 0.; i < N; i++) if (i!=I) {
        vec4 q = A(vec2(i,0)+.5);
        vec2 q0 = init(i);
        vec2 r = q.xy-Q.xy;
        float l = length(r);
        vec2 r0 = q0-Q0;
        float L = length(r0);
        if (l > 0.) {
            f += .1*r/l*(l-L)*exp(-.1*abs(I-i)-.1*L);
            f -= 10.*r/l*exp(-.01*l*l)*L/R.y;
        }
    }
    if (iMouse.z>0.) {
        f += .1*normalize(iMouse.xy-Q.xy);
    }
    if (Q.x<0.) f.x += -Q.x;
    if (R.x-Q.x<0.) f.x += R.x-Q.x;
    if (Q.y<0.) f.y += -Q.y;
    Q.zw += f;
    Q.xy += f+Q.zw;//*inversesqrt(1.+dot(Q.zw,Q.zw));
    if (iFrame < 1) {
        Q = vec4(Q0,0,0);
    }
}

