        vec2 u = vec2(mod(float(iFrame)*200.+i+U.x,N),0);
        vec4 q = A(u+.5);
        if (length(U-q.xy)<l) {
            l = length(U-q.xy);
            Q = vec4(u,0,0);
        }
    }
    for (float x = -3.; x <= 3.; x++)
    for (float y = -3.; y <= 3.; y++) {
        vec4 b = B(U+vec2(x,y));
        vec4 q = A(b.xy+.5);
        if (length(U-q.xy)<l) {
            l = length(U-q.xy);
            Q = b;
        }
    }
    for (float i = -10.; i<=10.; i++) {
        vec4 q = A(vec2(mod(Q.x+i,N),0)+.5);
        if (length(U-q.xy)<l) {
            l = length(U-q.xy);
            Q.x = mod(Q.x+i,N);
        }
    }
    Q.yzw = vec3(0);
}

